/// <reference types="node" />
// The browser icons (task app-icons): index.html links the SVG favicon first, the ICO as fallback
// and the Apple touch icon, and the files in public/ (copied as-is into the build) have the sizes
// the links promise. The raster files are generated by docs/brand/generate-icons.mjs.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

// `ng test` runs from the web/ folder.
const webRoot = process.cwd();
const publicFile = (name: string): Buffer => readFileSync(join(webRoot, 'public', name));

function iconLinks(): HTMLLinkElement[] {
  const html = readFileSync(join(webRoot, 'src', 'index.html'), 'utf8');
  const doc = new DOMParser().parseFromString(html, 'text/html');
  return Array.from(
    doc.head.querySelectorAll<HTMLLinkElement>('link[rel~="icon"], link[rel="apple-touch-icon"]'),
  );
}

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

/** Width and height from a PNG's IHDR chunk. */
function pngSize(png: Buffer): { width: number; height: number } {
  expect(png.subarray(0, 8).equals(PNG_SIGNATURE)).toBe(true);
  expect(png.toString('ascii', 12, 16)).toBe('IHDR');
  return { width: png.readUInt32BE(16), height: png.readUInt32BE(20) };
}

interface IcoEntry {
  width: number;
  height: number;
  image: Buffer;
}

/** Directory entries of an ICO file (0 in the size byte means 256 px). */
function icoEntries(ico: Buffer): IcoEntry[] {
  expect(ico.readUInt16LE(0)).toBe(0); // reserved
  expect(ico.readUInt16LE(2)).toBe(1); // type 1 = icon
  const count = ico.readUInt16LE(4);
  return Array.from({ length: count }, (_, i) => {
    const at = 6 + 16 * i;
    const size = ico.readUInt32LE(at + 8);
    const offset = ico.readUInt32LE(at + 12);
    expect(offset + size).toBeLessThanOrEqual(ico.length);
    return {
      width: ico.readUInt8(at) || 256,
      height: ico.readUInt8(at + 1) || 256,
      image: ico.subarray(offset, offset + size),
    };
  });
}

describe('app icons (index.html and public/)', () => {
  it('links the SVG favicon first, then the ICO fallback, then the touch icon', () => {
    const links = iconLinks().map((l) => [l.rel, l.getAttribute('href'), l.getAttribute('type')]);
    expect(links).toEqual([
      ['icon', 'favicon.svg', 'image/svg+xml'],
      ['icon', 'favicon.ico', null],
      ['apple-touch-icon', 'apple-touch-icon.png', null],
    ]);
  });

  it('declares the sizes the ICO actually contains', () => {
    const ico = iconLinks().find((l) => l.getAttribute('href') === 'favicon.ico');
    expect(ico?.getAttribute('sizes')).toBe('16x16 32x32 48x48');
  });

  it('favicon.svg is the brand mark and keeps its dark-mode switch', () => {
    const svg = publicFile('favicon.svg').toString('utf8');
    const brandMark = readFileSync(join(webRoot, '..', 'docs', 'brand', 'mark.svg'), 'utf8');
    expect(svg).toBe(brandMark);
    expect(svg).toContain('@media (prefers-color-scheme: dark)');
  });

  it('favicon.ico holds 16, 32 and 48 px images whose PNG data matches the directory', () => {
    const entries = icoEntries(publicFile('favicon.ico'));
    expect(entries.map((e) => [e.width, e.height])).toEqual([
      [16, 16],
      [32, 32],
      [48, 48],
    ]);
    for (const entry of entries) {
      expect(pngSize(entry.image)).toEqual({ width: entry.width, height: entry.height });
    }
  });

  it('apple-touch-icon.png is a 180 px square PNG', () => {
    expect(pngSize(publicFile('apple-touch-icon.png'))).toEqual({ width: 180, height: 180 });
  });

  it('apple-touch-icon.png is opaque (iOS fills transparent pixels black)', () => {
    // IHDR colour type at byte 25: 2 = RGB and 0 = greyscale have no alpha channel. A tRNS chunk
    // would add transparency to those, so it must be absent too.
    const png = publicFile('apple-touch-icon.png');
    expect([0, 2]).toContain(png.readUInt8(25));
    expect(png.includes(Buffer.from('tRNS', 'ascii'))).toBe(false);
  });
});
